// Pega todos os itens recebidos
const items = $input.all();

// Se não houver itens, começa do 001
if (items.length === 0) {
  const ano = new Date().getFullYear();
  const mes = String(new Date().getMonth() + 1).padStart(2, '0');
  const novoId = `${ano}${mes}-001`;

  return {
    json: {
      novo_id: novoId,
      sequencial: 1
    }
  };
}

// Extrai todos os números sequenciais dos nomes
const sequenciais = items.map(item => {
  const nome = item.json.name || '';
  const match = nome.match(/(\d{6})-(\d{3})/);
  return match ? parseInt(match[2], 10) : 0;
});

const maiorSequencial = Math.max(...sequenciais);
const novoSequencial = maiorSequencial + 1;

const ano = new Date().getFullYear();
const mes = String(new Date().getMonth() + 1).padStart(2, '0');
const sequencialFormatado = String(novoSequencial).padStart(3, '0');

const novoId = `${ano}${mes}-${sequencialFormatado}`;

return {
  json: {
    novo_id: novoId,
    sequencial: novoSequencial,
    ultimo_id_encontrado: `${ano}${mes}-${String(maiorSequencial).padStart(3, '0')}`
  }
};

const info = $('Pega todas as info.').first().json;
const mensagem4 = info.mensagem_4;
const mensagem6 = info.mensagem_6;
const dataBase = new Date(mensagem4.split('/').reverse().join('-'));
const normalized = mensagem6?.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const valor =
  mensagem6 === "Básico"
    ? parseFloat(info.mensagem_8.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."))
    : parseFloat(info.mensagem_8.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."));

const idValor =
  mensagem6 === "Básico"
    ? "YOUR_CLICKUP_FIELD_VALOR_BASICO_ID"
    : "YOUR_CLICKUP_FIELD_VALOR_AVANCADO_ID";

const horarioBruto = info.mensagem_5;
const [horaInicialStr, horaFinalStr] = horarioBruto.split(/-|às/).map(s => s.trim());

const [hIni, mIni] = horaInicialStr.split(':').map(Number);
const dataComHoraInicial = new Date(dataBase);
dataComHoraInicial.setHours(hIni, mIni, 0, 0);

const [hFim, mFim] = horaFinalStr.split(':').map(Number);
const dataComHoraFinal = new Date(dataBase);
dataComHoraFinal.setHours(hFim, mFim, 0, 0);

const timestampFinal = dataComHoraInicial.getTime() + (3 * 60 * 60 * 1000);
const timestampFinal2 = dataComHoraFinal.getTime() + (3 * 60 * 60 * 1000);

function campo(id, value, isDate = false) {
  return {
    id,
    body: isDate
      ? { value, value_options: { time: true } }
      : { value }
  };
}

return [
  campo("YOUR_CLICKUP_FIELD_DATE_START_ID", timestampFinal, true),
  campo("YOUR_CLICKUP_FIELD_DATE_END_ID", timestampFinal2, true),
  campo("YOUR_CLICKUP_FIELD_ENDERECO_ID", info.mensagem_3),
  campo(idValor, valor),
  campo("YOUR_CLICKUP_FIELD_HORARIO_ID", info.mensagem_5.replaceAll('-', 'às')),
  campo(
    "YOUR_CLICKUP_FIELD_TIPO_SUPORTE_ID",
    normalized === "basico"
      ? ["YOUR_CLICKUP_OPTION_BASICO_ID"]
      : normalized === "avancado"
      ? ["YOUR_CLICKUP_OPTION_AVANCADO_ID"]
      : ["YOUR_CLICKUP_OPTION_AVANCADO_ID", "YOUR_CLICKUP_OPTION_BASICO_ID"]
  ),
  campo(
    "YOUR_CLICKUP_FIELD_VALIDADE_ID",
    parseFloat(info.mensagem_7.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."))
  )
];

let resposta = ($json["resposta"] ?? "").toString().trim();
const validator = $json["validator"];

let valido = false;
let erro = "";

function validarHora(horaStr) {
    const regex = /^([0-1]?[0-9]|2[0-3]):([0-5][0-9])$/;
    return regex.test(horaStr);
}

function colapsarEspacos(s) {
    return s.replace(/\s+/g, ' ').trim();
}

function capitalizarPrimeira(s) {
    if (!s) return s;
    return s.charAt(0).toUpperCase() + s.slice(1);
}

function corrigirPlural(texto) {
    return texto.replace(/(\d+)\s+(dia|ano|mes|mês|hora|minuto|segundo|semana)(?!\w)/gi, (match, num, palavra) => {
        const numero = parseInt(num, 10);
        const palavraLower = palavra.toLowerCase();
        const plurais = {
            'dia': 'dias', 'ano': 'anos', 'mes': 'meses', 'mês': 'meses',
            'hora': 'horas', 'minuto': 'minutos', 'segundo': 'segundos', 'semana': 'semanas'
        };
        return numero === 1 ? `${num} ${palavraLower}` : `${num} ${plurais[palavraLower] || palavra}`;
    });
}

function validarEPadronizarData(dataStr) {
    const sep = dataStr.includes('/') ? '/' : (dataStr.includes('-') ? '-' : null);
    if (!sep) return null;
    const partes = dataStr.split(sep).map(p => p.trim());
    if (partes.length !== 3) return null;
    let [dd, mm, yyyy] = partes;
    if (!/^\d{1,2}$/.test(dd) || !/^\d{1,2}$/.test(mm) || !/^\d{4}$/.test(yyyy)) return null;
    const dia = parseInt(dd, 10);
    const mes = parseInt(mm, 10);
    const ano = parseInt(yyyy, 10);
    const dt = new Date(ano, mes - 1, dia);
    if (dt.getFullYear() !== ano || dt.getMonth() !== (mes - 1) || dt.getDate() !== dia) return null;
    return `${String(dia).padStart(2,'0')}/${String(mes).padStart(2,'0')}/${ano}`;
}

function formatarMoedaPTBR(valor) {
    try {
        return valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    } catch (e) {
        return 'R$ ' + valor.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    }
}

function normalizarTexto(texto) {
    return texto.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
}

switch (validator) {
    case "options_1_2_3":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else if (!["1","2","3"].includes(resposta)) { valido = false; erro = "Por favor, digite uma opção válida: 1, 2 ou 3."; }
        else { valido = true; }
        break;
    case "date":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else {
            const pad = validarEPadronizarData(resposta);
            if (!pad) { valido = false; erro = "Por favor, digite uma data válida no formato dd/MM/aaaa (exemplo: 25/12/2025)."; }
            else { resposta = pad; valido = true; }
        }
        break;
    case "time":
    case "datetime":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; break; }
        const partes = resposta.split('-').map(p => p.trim());
        if (partes.length !== 2) { valido = false; erro = "Use o formato hh:mm - hh:mm."; break; }
        const [inicio, fim] = partes;
        if (!validarHora(inicio) || !validarHora(fim)) { valido = false; erro = "Informe horários válidos no formato hh:mm - hh:mm."; break; }
        const [hi, mi] = inicio.split(':').map(Number);
        const [hf, mf] = fim.split(':').map(Number);
        if ((hi * 60 + mi) === (hf * 60 + mf)) { valido = false; erro = "Os horários não podem ser iguais."; break; }
        resposta = `${inicio} - ${fim}`; valido = true;
        break;
    case "text":
    case "pagamento":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else { resposta = capitalizarPrimeira(corrigirPlural(colapsarEspacos(resposta))); valido = true; }
        break;
    case "enum:basico,avancado":
        {
            const respostaNormalizada = normalizarTexto(resposta);
            if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
            else {
                const temBasico = respostaNormalizada.includes("basico");
                const temAvancado = respostaNormalizada.includes("avancado");
                const temAmbos = /ambos|dois|todos|ambas|os 2|2|os dois/.test(respostaNormalizada);
                if (temAmbos || (temBasico && temAvancado)) { resposta = "Ambos"; valido = true; }
                else if (temBasico) { resposta = "Básico"; valido = true; }
                else if (temAvancado) { resposta = "Avançado"; valido = true; }
                else { valido = false; erro = "Por favor, escolha entre: Básico, Avançado ou Ambos."; }
            }
        }
        break;
    case "number":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else {
            let s = resposta.replace(/[^\d.,-]/g, '').replace(/\s+/g, '');
            const virgulas = (s.match(/,/g)||[]).length;
            const pontos = (s.match(/\./g)||[]).length;
            if (pontos > 1 && virgulas === 0) s = s.replace(/\./g, '');
            else if (virgulas > 1 && pontos === 0) s = s.replace(/,/g, '');
            else if (pontos >= 1 && virgulas >= 1) { s = s.replace(/\./g, ''); s = s.replace(',', '.'); }
            else s = s.replace(',', '.');
            const valor = parseFloat(s);
            if (isNaN(valor) || valor <= 0) { valido = false; erro = "Por favor, informe um valor válido maior que zero (exemplo: R$ 120,00 ou 120)."; }
            else { valido = true; resposta = formatarMoedaPTBR(valor); }
        }
        break;
    case "prazo":
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else {
            const match = resposta.match(/(\d+)/);
            const dias = match ? parseInt(match[1], 10) : null;
            if (!dias || dias <= 0) { valido = false; erro = "Por favor, informe a validade em dias (exemplo: 7 dias, 10 ou 15 dias)."; }
            else { valido = true; resposta = dias === 1 ? "1 dia" : `${dias} dias`; }
        }
        break;
    default:
        if (!resposta) { valido = false; erro = "A resposta não pode ficar em branco."; }
        else { resposta = capitalizarPrimeira(corrigirPlural(colapsarEspacos(resposta))); valido = true; }
        break;
}

return { json: { resposta, valido, erro } };

const resposta = $json["resposta"]?.trim() || "";
const validator = $json["validator"];
let valido = false;
let erro = "";

const normalizar = (texto) =>
  texto.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();

switch (validator) {
  case "yesno": {
    if (!resposta) { erro = "A resposta não pode ser em branco!"; break; }
    const respostaNormalizada = normalizar(resposta);
    const opcoesValidas = ["sim", "s", "ok", "si", "nao", "n", "não", "ñ"];
    valido = opcoesValidas.includes(respostaNormalizada);
    if (!valido) erro = "Por favor me informe uma opção válida, como sim ou não";
    break;
  }
}

return { json: { resposta, valido, erro } };

