const info = $('Pega todas as info.').first().json;
const mensagem4 = info.mensagem_4;
const horarioBruto = info.mensagem_5;
const [horaInicialStr, horaFinalStr] = horarioBruto.split(/-|às/).map(s => s.trim());

const dataBase = new Date(mensagem4.split('/').reverse().join('-'));

const [hIni, mIni] = horaInicialStr.split(':').map(Number);
const dataComHoraInicial = new Date(dataBase);
dataComHoraInicial.setHours(hIni, mIni, 0, 0);

const [hFim, mFim] = horaFinalStr.split(':').map(Number);
const dataComHoraFinal = new Date(dataBase);
dataComHoraFinal.setHours(hFim, mFim, 0, 0);

const timestampFinal = dataComHoraInicial.getTime() + (3 * 60 * 60 * 1000);
const timestampFinal2 = dataComHoraFinal.getTime() + (3 * 60 * 60 * 1000);

function campo(id, value, isDate = false) {
  return {
    id,
    body: isDate
      ? { value, value_options: { time: true } }
      : { value }
  };
}

return [
  campo("YOUR_CLICKUP_FIELD_DATE_START_ID", timestampFinal, true),
  campo("YOUR_CLICKUP_FIELD_DATE_END_ID", timestampFinal2, true),
  campo("YOUR_CLICKUP_FIELD_ENDERECO_ID", info.mensagem_3),
  campo("YOUR_CLICKUP_FIELD_HORARIO_ID", info.mensagem_5.replaceAll("-", "às")),
  campo(
    "YOUR_CLICKUP_FIELD_TIPO_SUPORTE_ID",
    (() => {
      const msg6 = info.mensagem_6;
      const normalized = msg6?.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      if (normalized === "basico") return ["YOUR_CLICKUP_OPTION_BASICO_ID"];
      if (normalized === "avancado") return ["YOUR_CLICKUP_OPTION_AVANCADO_ID"];
      return ["YOUR_CLICKUP_OPTION_AVANCADO_ID", "YOUR_CLICKUP_OPTION_BASICO_ID"];
    })()
  ),
  campo(
    "YOUR_CLICKUP_FIELD_VALIDADE_ID",
    parseFloat(info.mensagem_7.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."))
  ),
  campo(
    "YOUR_CLICKUP_FIELD_VALOR_AVANCADO_ID",
    parseFloat(info.mensagem_13.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."))
  ),
  campo(
    "YOUR_CLICKUP_FIELD_VALOR_BASICO_ID",
    parseFloat(info.mensagem_12.replace(/[^\d.,]/g, "").replace(/\.(?=\d{3,})/g, "").replace(",", "."))
  )
];

